import './style.css';
import twemoji from '@twemoji/api';
import {ROLES,CHAPTERS,MISSIONS,SCENARIOS,REAL_WORLD,TODDLER,LESSONS,TOGETHER,DAILY,FATHER_DAYS,fatherCycle,PUZZLE_LABELS,missionStory} from './content.js';
import {load,persist,log,completions,nextMission,unlocked,today,recommendations,mergeEvents,normalize,fresh} from './store.js';
import {fa,mountPuzzle} from './puzzles.js';
import {createSyncClient} from './sync.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths={home:'M3 10 12 3l9 7v10h-6v-7H9v7H3Z',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Zm6-2v16m6-14v16',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',heart:'M12 21S1 14 3 7c2-5 7-4 9 0 2-4 7-5 9 0 2 7-9 14-9 14Z',book:'M12 5C8 2 4 3 2 4v16c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-2-10 1Zm0 0v16',sound:'m11 5-6 4H2v6h3l6 4Zm4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-6v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',arrow:'m14 6-6 6 6 6m-6-6h14',check:'m5 12 4 4L20 5',lock:'M6 10V7a6 6 0 0 1 12 0v3M5 10h14v11H5Z',close:'m6 6 12 12M6 18 18 6',cloud:'M6 19a5 5 0 0 1 0-10 7 7 0 0 1 13-1 5 5 0 0 1 0 11Zm6-12v9m-3-3 3 3 3-3',clock:'M12 7v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',leaf:'M20 3C7 0 0 9 6 16s17 3 14-13ZM4 21 17 7',mic:'M8 4a4 4 0 0 1 8 0v7a4 4 0 0 1-8 0Zm-3 6v1a7 7 0 0 0 14 0v-1m-7 8v4m-4 0h8'};
const icon=(name,size=21)=>`<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.star}"/></svg>`;
const availableEmoji=new Set(Object.keys(import.meta.glob('/public/assets/emoji/*.svg')).map(p=>p.split('/').pop().replace('.svg','')));
function paintEmoji(){twemoji.parse(document.body,{callback:name=>availableEmoji.has(name)?`./assets/emoji/${name}.svg`:false,attributes:()=>({draggable:'false'})});}
const emojiObserver=new MutationObserver(()=>{emojiObserver.disconnect();paintEmoji();emojiObserver.observe(document.body,{childList:true,subtree:true});});
let state=load();const edition=new URLSearchParams(location.search).get('edition');const fixedRole=ROLES.some(r=>r.id===edition)?edition:null;if(fixedRole)state.role=fixedRole;
let page='home',chapter=0,active=null,cleanup=()=>{},voicePlayer=null,voiceRun=0,voiceRole=state.role,gateNext=null,pauseUntil=0,syncBusy=false;
const sync=createSyncClient(()=>state.serverUrl);
const save=()=>{if(!persist(state))toast('ذخیره انجام نشد؛ فضای دستگاه را بررسی کنید.');};
const currentRole=()=>ROLES.find(r=>r.id===state.role);
const doneMissions=()=>completions(state,'explorer','mission');
const count=(role,kind)=>completions(state,role,kind).size;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function stopAudio(){voiceRun++;if(voicePlayer){voicePlayer.pause();voicePlayer.removeAttribute('src');voicePlayer.load();voicePlayer=null;}document.querySelectorAll('[data-audio-state]').forEach(e=>e.textContent='آمادهٔ شنیدن');}
async function playAudio(clip,role=state.role,voice=state.voices[role]){stopAudio();if(!state.sound){toast('صدا خاموش است؛ آن را در تنظیم صدا روشن کن.');return;}if(!/^[a-z-]+$/.test(clip))return;const src=`./assets/v2/voices/${voice==='second'?'second/':''}${clip}.mp3`;const my=voiceRun;const audio=new Audio(src);voicePlayer=audio;audio.onended=()=>{if(my===voiceRun)stopAudio();};audio.onerror=()=>{if(my===voiceRun){stopAudio();toast('این فایل صوتی پخش نشد. متن راهنما همچنان در دسترس است.');}};try{await audio.play();if(my===voiceRun)document.querySelectorAll('[data-audio-state]').forEach(e=>e.textContent='در حال پخش؛ برای توقف دکمه را بزن');}catch{if(my===voiceRun){stopAudio();toast('برای شنیدن دوباره دکمهٔ پخش را بزن.');}}}
const audioBar=(clip,label='بشنو و همراه شو',role=state.role)=>`<div class="audio-strip"><button data-action="audio" data-clip="${clip}" data-role="${role}" aria-label="${label}">${icon('sound',22)}</button><div><strong>${label}</strong><small data-audio-state>آمادهٔ شنیدن</small></div><div class="wave-bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><button class="audio-stop" data-action="stop-audio" aria-label="توقف صدا">■</button></div>`;
function closeModal(){cleanup();cleanup=()=>{};stopAudio();active=null;$('#modal-root').innerHTML='';document.body.classList.remove('f-modal-open');}
function modal(html,wide=false){cleanup();cleanup=()=>{};stopAudio();$('#modal-root').innerHTML=`<div class="f-overlay"><section class="f-modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="فعالیت خانواده"><button class="close-dialog" id="close-modal" data-action="close" aria-label="بستن">${icon('close')}</button>${html}</section></div>`;document.body.classList.add('f-modal-open');$('#close-modal').focus();}
function render(){stopAudio();const role=currentRole(),m=nextMission(state);$('#app').innerHTML=`<aside class="f-sidebar"><a class="f-brand" href="#" data-action="page" data-page="home"><span class="brand-mark">✳</span><div>باغِ قصه‌ها<small>با هم بازی کنیم، با هم رشد کنیم</small></div></a><div class="sidebar-rule"></div><div class="role-caption">${fixedRole?'نسخهٔ '+role.name:'همراهِ امروز تو'}</div>${fixedRole?`<div class="fixed-role"><span>${role.icon}</span><div><strong>${role.name}</strong><small>${role.age}</small></div></div>`:`<div class="role-switch">${ROLES.map(r=>`<button data-action="role" data-role="${r.id}" class="${r.id===state.role?'selected':''}" aria-label="نسخهٔ ${r.name}" aria-pressed="${r.id===state.role}"><span>${r.icon}</span><small>${r.name}</small></button>`).join('')}</div>`}<nav class="f-nav">${[['home','home',state.role==='toddler'?'بازیِ امروز':'خانهٔ من'],['journey','map',state.role==='explorer'?'مسیر ماجراجویی':state.role==='toddler'?'بازی‌های گفتاری':'مسیرِ یادگیری'],['together','heart','با هم بازی کنیم'],['journal','book','دفترِ پیشرفت'],['voices','sound','انتخاب صدا']].map(([id,ic,label])=>`<button class="${page===id?'active':''}" data-action="page" data-page="${id}">${icon(ic)}<span>${label}</span>${id==='journey'&&state.role==='explorer'?'<b>۲۰۰</b>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="gentle-reminder"><span>🌱</span><strong>رشد، مسابقه نیست.</strong><p>قدم‌های کوچک هم به حساب می‌آیند.</p></div><button class="sidebar-setting" data-action="protected-page" data-page="connect">${icon('cloud')} ارتباط خانواده</button><button class="sidebar-setting" data-action="protected-page" data-page="settings">${icon('settings')} تنظیمات و حریم خصوصی</button><small class="privacy-dot">بدون تبلیغ و خرید درون‌برنامه‌ای</small></div></aside><div class="f-workspace"><header class="f-topbar"><div class="breadcrumb">همراهِ خانواده <span>/</span> ${role.name}</div><div class="topbar-actions"><span class="top-message">یک قدم کوچک، یک اتفاق خوب ${icon('star',15)}</span><button class="top-voice" data-action="page" data-page="voices">${icon('sound',18)}<span>${state.voices[state.role]==='second'?'صدای دوم':'صدای اول'}</span></button><button class="top-avatar" data-action="profile" aria-label="تنظیمات پروفایل">${role.icon}</button></div></header><div class="f-layout ${state.role==='toddler'?'toddler-layout':''}"><main>${page==='home'?homePage():page==='journey'?journeyPage():page==='together'?togetherPage():page==='journal'?journalPage():page==='voices'?voicesPage():page==='connect'?connectPage():settingsPage()}</main>${!['voices','connect','settings'].includes(page)?railPage(m):''}</div><footer class="f-footer"><span>آرام، کنجکاو و مهربان؛ به اندازهٔ خودمان.</span><span>نسخهٔ ۲ · خانوادهٔ باغ قصه‌ها</span></footer></div>`;bindForms();}
function homePage(){if(state.role==='toddler')return toddlerHome();if(['mother','father'].includes(state.role))return parentHome();const m=nextMission(state),done=doneMissions();return `<div class="page-welcome"><div><span class="overline">یک ماجراجوییِ تازه منتظر توست</span><h1>سلام، ${esc(state.names.explorer)}! <span>👋</span></h1><p>امروز یک راز کشف کن، یک ایده بساز و کمی مهربانی بکار.</p></div><span class="welcome-orbit">✧</span></div><section class="journey-hero"><img src="./assets/v2/garden-journey.png" alt="باغ ایرانی با جوی آب، پل و روباه راهنما"><div class="journey-hero-copy"><span class="chapter-pill">فصل ${fa(m.chapter+1)} از ۱۰ · ${CHAPTERS[m.chapter].name}</span><h2>قصه با <em>انتخاب تو</em><br>جلو می‌رود!</h2><p>بشنو، کشف کن، بساز.<br>هر راه‌حل، یک اتفاق تازه در باغ.</p><button class="f-btn apricot" data-action="mission" data-id="${m.id}">${done.size?'ادامهٔ ماجراجویی':'شروع اولین ماجراجویی'} ${icon('arrow',18)}</button><span class="hero-meta">${icon('clock',13)} با توقف و ادامه، به اندازهٔ خودت</span></div><div class="fox-tag">🦊 من این‌جا همراهت هستم!</div></section><div class="f-stats"><div><span class="stat-illustration gold">✦</span><div><strong>${fa(done.size*100)} <small>برگِ تلاش</small></strong><p>برای قدم‌هایی که برداشتی</p></div></div><div><span class="stat-illustration green">${icon('check')}</span><div><strong>${fa(done.size)} <small>مأموریتِ کشف‌شده</small></strong><p>از ۲۰۰ ماجراجویی</p></div></div><div><span class="stat-illustration purple">${icon('star')}</span><div><strong>${fa(Math.min(40,1+Math.floor(done.size/5)))} <small>سطحِ سفر</small></strong><p>تجربه، نه نمرهٔ هوش</p></div></div></div><div class="section-title"><div><h2>قدم بعدی‌ات کاملاً روشن است</h2><p>یک مسیر، پنج ایستگاه، یک کشف واقعی</p></div><button data-action="page" data-page="journey" class="text-link">دیدن نقشه ${icon('arrow',15)}</button></div><section class="next-mission"><div class="mission-medal">${fa(m.local)}</div><div><span class="overline">${CHAPTERS[m.chapter].name} · سطح ${fa(m.level)}</span><h3>${m.title}</h3><div class="mission-tags"><span>قصه و انتخاب</span><span>${PUZZLE_LABELS[m.puzzles[0]]}</span><span>یک کار واقعی</span></div></div><button class="round-action" data-action="mission" data-id="${m.id}" aria-label="شروع ${m.title}">${icon('arrow')}</button></section><div class="five-stops">${['بشنو و انتخاب کن','کشفِ اول','چالشِ تازه','بیرون از صفحه','فکر و گفت‌وگو'].map((x,i)=>`<div><b>${fa(i+1)}</b><span>${x}</span></div>`).join('')}</div><div class="section-title"><div><h2>دنیای تو، بزرگ‌تر از یک بازی</h2><p>به موضوع‌های مختلف سر بزن و علاقهٔ خودت را پیدا کن.</p></div></div><div class="chapter-previews">${CHAPTERS.slice(0,3).map(c=>`<button data-action="chapter" data-id="${c.id}" class="chapter-preview tone-${c.id}"><span>${c.icon}</span><h3>${c.name}</h3><p>${c.skill}</p><small>${c.id?'بعد از فصل قبل':'آمادهٔ کشف'} ${icon(c.id?'lock':'arrow',13)}</small></button>`).join('')}</div><p class="bottom-kind">${icon('leaf',17)} این‌جا لازم نیست از کسی جلو بزنی؛ فقط فرصت تجربه‌کردن داری.</p>`;}
function railPage(m){const role=state.role;return `<aside class="f-rail"><section class="companion-card"><div class="companion-sky"><span>✧</span><div>${currentRole().icon}</div><span>✦</span></div><h3>${role==='explorer'?esc(state.names.explorer):role==='toddler'?esc(state.names.toddler):currentRole().name}</h3><span class="little-label">${role==='explorer'?'کاوشگرِ باغ قصه‌ها':role==='toddler'?'با همراهی یک بزرگ‌تر':'یک همراه، نه یک والد بی‌نقص'}</span><div class="rail-divider"></div><p>${role==='explorer'?'انتخاب می‌کنی، تجربه می‌کنی و از نتیجه یاد می‌گیری.':role==='toddler'?'اشاره، نگاه و صدا؛ هر راه ارتباط ارزشمند است.':'برنامه باید به زندگی شما کمک کند، نه فشار تازه‌ای بسازد.'}</p></section><section class="rail-audio"><div class="rail-title"><h3>با صدای مهربان</h3>${icon('sound',17)}</div><p>مقدمهٔ مخصوص ${currentRole().name}</p>${audioBar(role+'-welcome','صدای همراهِ من',role)}<button class="text-link" data-action="page" data-page="voices">انتخاب بین دو صدا ${icon('arrow',14)}</button></section><section class="rail-together"><div class="rail-title"><h3>قرارِ کوچک خانواده</h3><span>♡</span></div><div class="together-art">🌷</div><strong>امروز، یک بازی با هم</strong><p>برای هر سن یک نقش؛ بدون مقایسه و مسابقه.</p><button class="f-btn light" data-action="page" data-page="together">بازی مشترک را ببین</button></section><button class="rail-rest" data-action="rest">${icon('leaf',27)}<span><strong>یک مکثِ مهربان</strong><small>از صفحه فاصله بگیر؛ باغ منتظرت می‌ماند.</small></span></button></aside>`;}
function journeyPage(){if(state.role==='toddler')return toddlerHome(true);if(['mother','father'].includes(state.role))return lessonsPage();const c=CHAPTERS[chapter];return `<div class="page-welcome"><div><span class="overline">۱۰ فصل · ۲۰۰ مأموریت · ۱۰۰۰ ایستگاه</span><h1>نقشهٔ باغِ قصه‌ها</h1><p>فقط یک قدم بعدی؛ لازم نیست همهٔ راه را امروز بروی.</p></div></div><div class="chapter-tabs">${CHAPTERS.map(c=>`<button data-action="chapter" data-id="${c.id}" class="${chapter===c.id?'selected':''}"><span>${c.icon}</span><small>${c.name}</small></button>`).join('')}</div><div class="map-header"><div><span>فصل ${fa(chapter+1)}</span><h2>${c.name}</h2><p>${c.skill}</p></div><button class="favorite-button ${state.favorites.includes(chapter)?'selected':''}" data-action="favorite" data-id="${chapter}">${icon('heart',17)} ${state.favorites.includes(chapter)?'از علاقه‌های من':'دوست دارم تجربه کنم'}</button></div><div class="mission-map"><div class="map-landscape"></div><svg class="map-river" viewBox="0 0 600 1200" preserveAspectRatio="none"><path d="M300 20 C50 100 50 190 300 240 S550 410 300 470 S50 650 300 710 S550 890 300 950 S50 1120 300 1190"/></svg>${MISSIONS.filter(m=>m.chapter===chapter).map((m,i)=>{const done=doneMissions().has(String(m.id)),open=unlocked(state,m.id);return `<div class="map-stop position-${i%4}"><button data-action="mission" data-id="${m.id}" class="map-node ${done?'done':open?'current':'locked'}" aria-label="مرحله ${fa(m.id)} ${m.title}${open?'':' قفل است'}">${done?icon('check',26):open?fa(m.local):icon('lock',20)}</button><div class="map-stop-label"><strong>${m.title}</strong><span>${done?'کشف شد؛ تمرین دوباره':open?'اینجا قدم بعدی توست':`بعد از مأموریت ${fa(m.id-1)}`}</span></div>${(i+1)%5===0?'<span class="checkpoint">✦</span>':''}</div>`;}).join('')}<div class="map-end">${c.icon}<strong>نشان «${c.badge}»</strong><span>پس از ۲۰ مأموریتِ این فصل</span></div></div>`;}
function toddlerHome(library=false){return `<div class="toddler-heading"><span class="overline">فقط چند دقیقه، کنار مامان یا بابا</span><h1>${library?'بازی‌های گفتاریِ جوانه':`سلام ${esc(state.names.toddler)}!`}</h1><p>بشنو، نشان بده، بازی کن. گفتنِ کلمه اجباری نیست.</p></div><div class="toddler-welcome"><div class="toddler-sun">☀️</div><div class="toddler-blossom">🌱</div><h2>امروز با چی بازی کنیم؟</h2><span>۳ خانوادهٔ واژه · ۱۲ بازی کوتاه و تکرارِ هدفمند</span></div><div class="toddler-gallery">${TODDLER.map(t=>`<button class="toddler-game ${t.theme}" data-action="toddler" data-id="${t.id}"><span>${objectArt(t.theme)}</span><h3>${t.title}</h3><p>با بزرگ‌تر · حدود ۲–۴ دقیقه</p><small>${completions(state,'toddler','toddler').has(String(t.id))?'یک بار با هم تجربه کردیم':'بیا بازی کنیم'}</small></button>`).join('')}</div><div class="parent-tip"><strong>برای بزرگ‌ترِ کنار کودک</strong><p>هر واژه را روشن و طبیعی بگویید؛ پاسخ کودک را گسترش بدهید، نه اینکه مرتب تصحیح کنید. این برنامه گفتاردرمانی نیست. تکرار بازی برای خردسال اختیاری و هدفمند است؛ زمان صفحه را کوتاه نگه دارید و ادامهٔ بازی را بیرون از صفحه انجام دهید.</p></div>`;}
function objectArt(theme){return theme==='ball'?'<svg viewBox="0 0 140 140"><circle cx="70" cy="70" r="54" fill="#ffb96e"/><path d="M25 42q50 10 87 61M33 108q42-51 53-87" stroke="#fff1d9" stroke-width="15" fill="none"/><path d="M39 25q51 19 80 47" fill="none" stroke="#de8056" stroke-width="6" opacity=".4"/></svg>':theme==='water'?'<svg viewBox="0 0 140 140"><path d="M70 12C53 39 25 65 25 85a45 45 0 0 0 90 0C115 64 88 38 70 12" fill="#7bc8de"/><path d="M44 73q-12 31 17 40" fill="none" stroke="#c9f3f9" stroke-width="9" stroke-linecap="round"/><circle cx="58" cy="82" r="3" fill="#3e6c86"/><circle cx="82" cy="82" r="3" fill="#3e6c86"/><path d="M60 95q10 10 20 0" fill="none" stroke="#3e6c86" stroke-width="3"/></svg>':'<svg viewBox="0 0 140 140"><path d="M72 38C20 4 8 62 27 104s42 17 45 18c5 0 38 30 49-21S113 9 72 38" fill="#e8847e"/><path d="M71 36q-3-19 10-27" fill="none" stroke="#79543f" stroke-width="8" stroke-linecap="round"/><path d="M74 27q10-33 39-17-4 30-39 17" fill="#8abc86"/><path d="M43 48q-17 10-12 30" fill="none" stroke="#ffc4b9" stroke-width="8" stroke-linecap="round"/></svg>';}
function parentHome(){const father=state.role==='father',cycle=fatherCycle(state.cycleStart,today()),role=state.role;const tasks=state.energy==='low'?DAILY.filter((_,i)=>[0,3,4].includes(i)):DAILY;const finished=completions(state,role,'routine');return `<div class="page-welcome"><div><span class="overline">برنامهٔ قابل تغییر برای یک زندگی واقعی</span><h1>${currentRole().title}</h1><p>${father?'در هر بخش از چرخه، یک سهم روشن و شدنی داشته باش.':'امروز به اندازهٔ انرژی خودت پیش برو؛ برنامه خدمت‌گزار توست.'}</p></div></div><section class="parent-hero ${father?'father-hero':''}"><div><span class="chapter-pill">${father?`روز ${fa(cycle.day)} از ۱۵ · ${cycle.away?'دورهٔ دوری':'کنار خانواده'}`:'یک همراه، بدون قضاوت'}</span><h2>${father?FATHER_DAYS[cycle.day-1]:'ارتباطِ کوچک،<br>اثرِ ماندگار'}</h2><p>${father?(cycle.away?'یک تماس کوتاه با توجه، و یک هماهنگی روشن با مادر.':'اول گوش کن؛ بعد یک مسئولیت واقعی از کارهای خانه و بچه‌ها بپذیر.'):'برای یادگیری لازم نیست مدام آموزش بدهیم؛<br>بازی، شنیدن و رفتار روزمره هم فرصت‌اند.'}</p><button class="f-btn apricot" data-action="lesson" data-id="${father?(cycle.away?13:14):1}">${father?'برنامهٔ این دوره':'تمرینِ موقعیت امروز'} ${icon('arrow',17)}</button></div><div class="parent-hero-art">${father?'🌳':'🌷'}<span>♡</span></div></section>${father?`<div class="cycle-strip">${FATHER_DAYS.map((_,i)=>`<span class="${i+1===cycle.day?'current':''} ${i>=10?'home-day':''}" title="${FATHER_DAYS[i]}">${fa(i+1)}</span>`).join('')}</div><p class="muted-text">روزهای ۱ تا ۱۰ دوری؛ ۱۱ تا ۱۵ حضور. تاریخ شروع را در تنظیمات تغییر بده.${cycle.future?' شروع چرخه هنوز نرسیده است.':''}</p>`:''}${familyOverview()}<div class="section-title"><div><h2>انرژی امروزت چقدر است؟</h2><p>این پاسخ نمره ندارد؛ فقط حجم برنامه را تنظیم می‌کند.</p></div></div><div class="energy-picker">${[['low','کم؛ سبک‌تر پیش برویم'],['normal','معمولی؛ قدم‌های کوتاه'],['high','خوب؛ یک بازی بیشتر']].map(([id,t])=>`<button data-action="energy" data-value="${id}" class="${state.energy===id?'selected':''}">${t}</button>`).join('')}</div><div class="section-title"><div><h2>قرارهای کوچکِ امروز</h2><p>انجام‌نشده‌ها بدهی نیستند. می‌توانی فردا برنامه را عوض کنی.</p></div></div><div class="routine-list">${tasks.map(([id,t,desc])=>{const key=today()+':'+id,done=finished.has(key);return `<button class="routine-item ${done?'done':''}" data-action="routine" data-id="${id}"><span class="check-circle">${done?icon('check',18):''}</span><div><h3>${t}</h3><p>${desc}</p></div><small>${done?'ثبت شد':'انجام دادم'}</small></button>`;}).join('')}</div><div class="section-title"><div><h2>پیشنهادهای شفاف، نه تشخیص شخصیت</h2></div></div><div class="recommendations">${recommendations(state).map(r=>`<article><span>🌱</span><h3>${r.title}</h3><small>چرا؟ ${r.why}</small><p>${r.action}</p></article>`).join('')}</div>`;}
function familyOverview(){return `<div class="section-title"><div><h2>خبرِ کوچکِ بچه‌ها</h2><p>اطلاعات همین دستگاه؛ پس از همگام‌سازی، تجربه‌های دستگاه‌های دیگر هم دیده می‌شوند.</p></div></div><div class="family-overview">${['explorer','toddler'].map(role=>{const events=state.events.filter(e=>e.role===role),n=count(role,role==='explorer'?'mission':'toddler');return `<button data-action="review-child" data-role="${role}"><span>${role==='explorer'?'🦊':'🌱'}</span><div><strong>${esc(state.names[role])}</strong><p>${fa(n)} ${role==='explorer'?'مأموریت کشف‌شده':'بازی تجربه‌شده'}</p><small>${events.length?'آخرین ثبت: '+new Date(events[events.length-1].at).toLocaleDateString('fa-IR'):'هنوز تجربه‌ای ثبت نشده'}</small></div>${icon('arrow',18)}</button>`;}).join('')}</div>`;}
function lessonsPage(){return `<div class="page-welcome"><div><span class="overline">۱۵ موقعیت واقعی · تمرین، نه امتحان والدگری</span><h1>کارگاهِ همراهی</h1><p>یک موقعیت را ببین، پاسخ را مقایسه کن و یک کار کوچک در زندگی امتحان کن.</p></div></div><div class="lesson-grid">${LESSONS.map(l=>`<button class="lesson-card" data-action="lesson" data-id="${l.id}"><span class="lesson-index">${fa(l.id)}</span><h3>${l.title}</h3><p>${l.situation}</p><small>${completions(state,state.role,'lesson').has(String(l.id))?'تمرین ثبت شده · مرور':'شروع تمرین'} ${icon('arrow',15)}</small></button>`).join('')}</div>`;}
function togetherPage(){return `<div class="page-welcome"><div><span class="overline">دو سن، دو نقش، یک تجربهٔ مشترک</span><h1>با هم بازی کنیم ♡</h1><p>بزرگ‌تر مسئول ایمنی می‌ماند؛ کودک بزرگ‌تر، مراقبِ اجباریِ کودک کوچک‌تر نیست.</p></div></div><div class="together-grid">${TOGETHER.map(t=>`<article class="together-card"><div class="together-cover">${t.icon}</div><div><span class="overline">${t.time} · بیرون از صفحه</span><h2>${t.name}</h2><p>${t.materials}</p><button class="f-btn light" data-action="together" data-id="${t.id}">نقشِ هر کدام را ببین ${icon('arrow',17)}</button></div></article>`).join('')}</div>`;}
function journalPage(){const role=state.role,events=state.events.filter(e=>e.role===role).slice().reverse(),done=doneMissions();return `<div class="page-welcome"><div><span class="overline">ثبت تجربه‌ها؛ بدون برچسب‌زدن</span><h1>دفترِ پیشرفت ما</h1><p>این گزارش فقط کارهای ثبت‌شده و علاقه‌های گفته‌شده را نشان می‌دهد، نه هوش یا تشخیص شخصیت.</p></div></div>${role==='explorer'?`<div class="journal-summary"><span>🌳</span><div><h2>${fa(done.size)} مأموریت، ${fa(done.size*100)} برگِ تلاش</h2><p>هر برگ نشانهٔ یک تجربه است؛ نه برتری نسبت به کسی.</p></div></div><div class="badge-gallery">${CHAPTERS.map(c=>{const n=[...done].filter(id=>MISSIONS[+id-1]?.chapter===c.id).length;return `<div class="badge-item ${n===20?'earned':''}"><span>${c.icon}</span><strong>${c.badge}</strong><small>${fa(n)} از ۲۰ مأموریت</small><div class="progress-line"><i style="width:${n*5}%"></i></div></div>`;}).join('')}</div>`:`<div class="journal-summary"><span>${currentRole().icon}</span><div><h2>${fa(events.length)} تجربهٔ ثبت‌شده</h2><p>${role==='toddler'?'نگاه، اشاره و کلمه؛ بدون نمرهٔ تلفظ':'تمرین‌های واقعی، نه نمرهٔ خوب یا بد بودن والد'}</p></div></div>`}<div class="section-title"><h2>تازه‌ترین تجربه‌ها</h2><button class="text-link" data-action="protected-export">دریافت نسخهٔ پشتیبان ${icon('cloud',15)}</button></div>${events.length?`<div class="timeline-list">${events.slice(0,30).map(e=>`<div><span class="timeline-dot"></span><article><small>${new Date(e.at).toLocaleDateString('fa-IR')}</small><h3>${esc(eventTitle(e))}</h3><p>${esc(e.data.observation||e.data.reflection||e.data.interest||'یک قدم کوچک ثبت شد.')}</p></article></div>`).join('')}</div>`:'<div class="empty-state"><span>🌱</span><h3>اولین تجربه منتظر توست</h3><p>از خانه یک فعالیت انتخاب کن؛ این‌جا کم‌کم پر می‌شود.</p><button class="f-btn" data-action="page" data-page="home">برگشت به خانه</button></div>'}${state.art.length?`<h2>گالریِ خیال</h2><div class="art-gallery">${state.art.map(a=>`<img src="${a}" alt="نقاشی ذخیره‌شدهٔ خانواده">`).join('')}</div>`:''}`;}
function eventTitle(e){return e.kind==='mission'?MISSIONS[+e.subject-1]?.title||'مأموریت':e.kind==='toddler'?TODDLER[+e.subject-1]?.title||'بازی گفتاری':e.kind==='lesson'?LESSONS[+e.subject-1]?.title||'تمرین والد':e.kind==='together'?TOGETHER[+e.subject-1]?.name||'بازی مشترک':e.kind==='routine'?DAILY.find(d=>e.subject.endsWith(':'+d[0]))?.[1]||'قرار روزانه':'گفت‌وگو';}
function voicesPage(){return `<div class="page-welcome"><div><span class="overline">دو صدای زن · فارسی ایران</span><h1>صدای همراهت را انتخاب کن</h1><p>هر نقش می‌تواند صدای دلخواه خودش را داشته باشد.</p></div></div><div class="voice-role-picker">${ROLES.map(r=>`<button data-action="voice-role" data-role="${r.id}" class="${voiceRole===r.id?'selected':''}">${r.icon} ${r.name}</button>`).join('')}</div><div class="voice-cards">${['first','second'].map((v,i)=>`<article class="voice-card ${state.voices[voiceRole]===v?'selected':''}"><div class="voice-portrait tone-${i}">${icon('sound',40)}</div><h2>صدای ${i?'دوم':'اول'}</h2><p>راوی زن · فارسی ایران</p><button class="f-btn light" data-action="preview-voice" data-value="${v}">${icon('sound',18)} شنیدن نمونه</button><button class="f-btn ${state.voices[voiceRole]===v?'chosen':''}" data-action="select-voice" data-value="${v}">${state.voices[voiceRole]===v?'انتخاب فعلی ✓':'این صدا را انتخاب می‌کنم'}</button></article>`).join('')}</div><div class="voice-utilities"><button class="f-btn light" data-action="stop-audio">توقف پخش</button><button class="f-btn light" data-action="sound">${state.sound?'صدا روشن است؛ خاموش کن':'صدا خاموش است؛ روشن کن'}</button></div><p class="notice-note">انتخاب روی همین دستگاه ذخیره می‌شود. مقدمه‌ها، سه خانوادهٔ واژه، دو داستان و راهنمای ترمیم با هر دو صدا ضبط شده‌اند؛ برای باقی متن‌ها هنوز گویندگی کامل نداریم و صدای جایگزینِ تأییدنشده پخش نمی‌کنیم.</p>`;}
function connectPage(){const native=navigator.userAgent.includes('LittleStarAndroid');return `<div class="page-welcome"><div><span class="overline">فقط با اجازهٔ والدین</span><h1>پلِ ارتباط خانواده</h1><p>گزارش‌ها را آگاهانه بین دستگاه‌ها به اشتراک بگذارید؛ صدای ضبط‌شده ارسال نمی‌شود.</p></div></div><div class="connection-notice"><strong>${state.serverUrl?'سرور انتخابی خانواده':native?'سرور دائمی هنوز تنظیم نشده':'اتصال آزمایشی همین محیط'}</strong><p>${native?'برای اتصال اینترنتی، نشانی HTTPS یک سرور خانوادهٔ مستقرشده لازم است. فایل نصب به‌تنهایی سرور دائمی ایجاد نمی‌کند.':'API این محیط برای آزمایش است؛ روشن‌بودن پیش‌نمایش به معنی استقرار دائمی یا پشتیبان‌گیری تضمین‌شده نیست.'}</p></div><section class="form-card"><form id="server-form"><label>نشانی سرورِ مورد اعتماد<input name="server" type="url" dir="ltr" placeholder="https://your-family-server.example" value="${esc(state.serverUrl)}"></label><p class="field-note">فقط سروری که مالک آن را می‌شناسید. اطلاعات ورود به همین نشانی ارسال می‌شود. خالی‌گذاشتن در وب، سرور همین محیط را استفاده می‌کند.</p><button class="f-btn light">ذخیرهٔ نشانی</button></form></section>${sync.loggedIn?`<section class="form-card"><span class="connection-state">وارد شده‌اید: ${esc(sync.username)}</span><p>با همین حساب والدین در نسخه‌های دیگر وارد شوید. با فشردن همگام‌سازی، تجربه‌های ثبت‌شده ترکیب می‌شوند.</p><button class="f-btn" data-action="sync" ${syncBusy?'disabled':''}>${syncBusy?'در حال همگام‌سازی…':'ارسال و دریافت گزارش‌ها'}</button><button class="f-btn light" data-action="logout">خروج از حساب</button><p id="sync-status" role="status"></p><button class="danger-link" data-action="delete-account">حذف حساب و گزارش‌های سرور</button></section>`:`<section class="form-card"><h2>حساب مشترک والدین</h2><p>اطلاعات کودک، نام واقعی و ایمیل لازم نیست. یک نام کاربری مستعار انتخاب کنید.</p><form id="login-form"><label>نام کاربری انگلیسی<input name="username" dir="ltr" autocomplete="username" pattern="[A-Za-z0-9_-]{3,40}" minlength="3" maxlength="40" required></label><label>رمز حساب والدین<input name="password" dir="ltr" type="password" autocomplete="current-password" minlength="10" maxlength="128" required></label><label class="checkbox-label"><input type="checkbox" name="consent" required> والد هستم و ارسال گزارش‌های فعالیت به این سرور را می‌پذیرم.</label><div class="form-buttons"><button class="f-btn" name="mode" value="login">ورود</button><button class="f-btn light" name="mode" value="register">ساخت حساب</button></div><p id="login-status" role="status"></p></form><p class="field-note">رمز در برنامه ذخیره نمی‌شود. پس از بستن برنامه ممکن است دوباره ورود لازم باشد. بازیابی خودکار رمز هنوز نداریم؛ رمز را نزد خودتان نگه دارید.</p></section>`}<section class="form-card"><h3>بدون سرور هم داده‌ها دست خودتان است</h3><p>فایل پشتیبان را خودتان به دستگاه دیگر منتقل و در تنظیمات وارد کنید. فایل شامل یادداشت‌های خانواده است؛ فقط با افراد مورد اعتماد به اشتراک بگذارید.</p><button class="f-btn light" data-action="export">دریافت فایل پشتیبان</button></section>`;}
function settingsPage(){return `<div class="page-welcome"><div><h1>تنظیماتِ همراه خانواده</h1><p>انتخاب‌های روشن برای حریم خصوصی و تعادل زندگی.</p></div></div><section class="form-card"><form id="settings-form"><label>نام مستعار کودک بزرگ‌تر<input name="explorer" value="${esc(state.names.explorer)}" maxlength="24" required></label><label>نام مستعار خردسال<input name="toddler" value="${esc(state.names.toddler)}" maxlength="24" required></label><label>اولین روزِ دورهٔ ۱۰ روز کار پدر<input name="cycle" type="date" value="${state.cycleStart}" required></label><label>وقفهٔ بازی کودک بزرگ‌تر پس از<select name="limit">${[15,20,30].map(n=>`<option value="${n}" ${n===state.limit?'selected':''}>${fa(n)} دقیقه</option>`).join('')}</select></label><button class="f-btn">ذخیرهٔ تنظیمات</button></form></section><section class="form-card"><h2>داده‌های خانواده</h2><p>اطلاعات به‌صورت محلی ذخیره می‌شود؛ ارسال به سرور تنها با ورود والد و دکمهٔ همگام‌سازی انجام می‌شود. ضبط صدا اختیاری، موقت و فقط برای بازپخش در همان پنجره است.</p><div class="form-buttons"><button class="f-btn light" data-action="export">دریافت پشتیبان</button><label class="f-btn light file-label">واردکردن پشتیبان<input id="import-backup" type="file" accept=".json,.txt,application/json,text/plain" hidden></label></div><button class="danger-link" data-action="reset">پاک‌کردن اطلاعات همین دستگاه</button></section><section class="form-card editorial-notice"><h2>مرزهای آموزشی و سلامت</h2><p>راهنماها آموزشی‌اند؛ نه گفتاردرمانی، تشخیص هوش، استعداد، شخصیت یا سلامت روان. در نگرانی پایدار دربارهٔ گفتار، شنوایی، خواب یا رفتار، از متخصص مناسب کمک بگیرید. در خطر فوریِ آسیب به کودک، کمک فوری محلی بگیرید.</p><p>برای ۲–۳ ساله جلسات کوتاه همراه بزرگ‌تر طراحی شده‌اند. راهنمای WHO برای این سن حداکثر یک ساعت مجموع زمان نشستهٔ صفحه در روز و کمتر بهتر است؛ این سقف، هدف روزانهٔ برنامه نیست. بازی بدنی، گفت‌وگو و خواب مقدم‌اند.</p><p>محتوای ارزشی با رویکرد اسلامی شیعه، محبت، دعا، انصاف و شکرگزاری ارائه می‌شود؛ بدون اجبار، ترساندن یا نمرهٔ ایمان. بازگویی‌های شاهنامه افسانهٔ ادبی‌اند، نه تاریخ یا علم.</p><p>۲۰۰ مأموریت از ۲۰ الگوی معما و روایت‌های موقعیتی در ۱۰ زمینهٔ داستانی ساخته شده‌اند؛ همهٔ آن‌ها ۲۰۰ داستان یا انیمیشن مستقل نیستند. این نسخه پیش از انتشار گسترده به بررسی تخصصی و آزمون با کودکان نیاز دارد.</p><p>منابع راهنما: ASHA، «Communication Milestones: 2 to 3 Years»؛ WHO، «To grow up healthy, children need to sit less and play more». قلم وزیرمتن با OFL، نمادهای Twemoji با CC BY 4.0؛ تصویر باغ با هوش مصنوعی ساخته شده است.</p></section>`;}
function missionHeader(m,step){return `<div class="activity-overline"><span>مأموریت ${fa(m.id)} · ${CHAPTERS[m.chapter].name}</span><span>${fa(step+1)} از ۵</span></div><div class="activity-progress">${Array.from({length:5},(_,i)=>`<i class="${i<=step?'filled':''}"></i>`).join('')}</div>`;}
function startMission(id){if(Date.now()<pauseUntil){showRest();return;}if(state.activeSeconds>=state.limit*60){showRest(true);return;}const m=MISSIONS[id-1];if(!m)return;if(!unlocked(state,id)){toast(`اول مأموریت ${fa(id-1)} را کشف کن. مسیرت را قدم‌به‌قدم می‌سازیم.`);return;}const raw=state.drafts['mission:'+id],saved=doneMissions().has(String(id))?null:raw;active={kind:'mission',id,step:Number.isInteger(saved?.step)?Math.min(4,Math.max(0,saved.step)):0,hints:Number(saved?.hints)||0,attempts:Number(saved?.attempts)||0,ready:false};showMission();}
function saveDraft(){if(active?.kind==='mission'){state.drafts['mission:'+active.id]={step:active.step,hints:active.hints,attempts:active.attempts};save();}}
function missionReady(){if(!active)return;active.ready=true;const b=$('#advance-activity');if(b)b.disabled=false;}
function showMission(){const a=active,m=MISSIONS[a.id-1],scene=missionStory(m);a.ready=false;const step=a.step;const titles=['قصه را بشنو، انتخاب کن',PUZZLE_LABELS[m.puzzles[0]],PUZZLE_LABELS[m.puzzles[1]],'حالا بیرون از صفحه','کشف تو چه بود؟'];modal(`${missionHeader(m,step)}<h2 class="activity-heading">${titles[step]}</h2><p class="activity-subtitle">${m.title} · سطح ${fa(m.level)}</p><div id="activity-content"></div><div class="activity-navigation"><button class="f-btn" id="advance-activity" data-action="advance" disabled>${step===4?'ثبت دستاوردم':'قدم بعدی'} ${icon('arrow',17)}</button><button class="text-link" data-action="close">ذخیره شده؛ بعداً ادامه می‌دهم</button></div>`,true);const root=$('#activity-content');
 if(step===0){root.innerHTML=`<div class="story-stage scene-${m.chapter}"><span class="story-sun">☀️</span><span class="story-character">🦊</span><span class="story-object">${scene.icon}</span><div class="story-ground"></div></div>${scene.audio?audioBar(scene.audio,'قصه را با صدای راوی بشنو','explorer'):audioBar('explorer-welcome','راهنمای کلی سفر؛ متن قصه پایین است','explorer')}<h3>${scene.title}</h3><p class="story-paragraph">${scene.text}</p><div class="answer-options">${scene.choices.map((t,i)=>`<button data-story-choice="${i}">${t}</button>`).join('')}</div><div class="story-feedback" role="status"></div>`;root.querySelectorAll('[data-story-choice]').forEach(b=>b.onclick=()=>{if(+b.dataset.storyChoice===scene.answer){b.classList.add('right');root.querySelectorAll('[data-story-choice]').forEach(x=>x.disabled=true);root.querySelector('.story-feedback').textContent=scene.why;missionReady();}else{a.attempts++;root.querySelector('.story-feedback').textContent='به پیامد این انتخاب برای خودت و دیگران فکر کن. راه امن‌تر یا دقیق‌تری هم هست؛ دوباره انتخاب کن.';}});}
 if(step===1||step===2){cleanup=mountPuzzle(root,m.puzzles[step-1],m,{sound:state.sound,onSolve:stats=>{a.attempts+=stats.attempts;missionReady();},onHint:()=>{a.hints++;saveDraft();}});}
 if(step===3){const r=REAL_WORLD[m.chapter];root.innerHTML=`<div class="offscreen-mark">🌱</div><h3>${r[0]}</h3><p class="story-paragraph">${r[1]}</p><div class="safety-note">${r[2]}</div><label class="checkbox-label activity-check"><input type="checkbox" id="real-done"> این کار را انجام دادم یا با بزرگ‌تر، شکل مناسب توان خودم را امتحان کردم.</label><button class="f-btn light" data-action="draw">اگر دوست داری، ایده‌ات را نقاشی کن</button><p class="muted-text">اگر وسایل یا همراه مناسب نداری، «بعداً ادامه می‌دهم» را بزن. عجله یا جریمه‌ای در کار نیست.</p>`;$('#real-done').onchange=e=>{a.ready=e.target.checked;$('#advance-activity').disabled=!a.ready;};}
 if(step===4){root.innerHTML=`<p class="story-paragraph">کدام بخش این تجربه برایت جالب‌تر بود؟ همهٔ پاسخ‌ها پذیرفته‌اند. لازم نیست یک علاقهٔ همیشگی انتخاب کنی.</p><div class="reflection-options">${['قصه و گفت‌وگو','پیداکردن راه‌حل','ساختن و آزمایش','هنوز مطمئن نیستم'].map(t=>`<button data-reflect="${t}">${t}</button>`).join('')}</div><label class="text-label">اگر دوست داشتی، یک جمله دربارهٔ کشفت بنویس<textarea id="mission-note" maxlength="300" placeholder="اول فکر می‌کردم… بعد فهمیدم…"></textarea></label>${recorderMarkup()}<p class="muted-text">هیچ پاسخ شخصی یا ضبط صدایی اجباری نیست.</p>`;root.querySelectorAll('[data-reflect]').forEach(b=>b.onclick=()=>{a.interest=b.dataset.reflect;root.querySelectorAll('[data-reflect]').forEach(x=>x.classList.toggle('selected',x===b));missionReady();});attachRecorder();}
}
function advance(){if(!active?.ready)return;const a=active;if(a.kind==='mission'){if(a.step<4){a.step++;saveDraft();showMission();return;}const m=MISSIONS[a.id-1],note=$('#mission-note')?.value||'';const was=doneMissions().has(String(a.id));if(!was)log(state,'explorer','mission',a.id,{hints:a.hints,attempts:a.attempts,interest:a.interest,reflection:note,chapter:m.chapter});delete state.drafts['mission:'+a.id];save();active=null;render();modal(`<div class="reward-bloom">🌳<span>✦</span><i>✧</i></div><span class="overline">مأموریت ${fa(a.id)} · ${m.title}</span><h2>با تلاشت، باغ یک قدم زنده‌تر شد!</h2><p class="story-paragraph">${was?'این بار برای لذتِ تمرین برگشتی؛ امتیاز تکراری نمی‌گیری.':'۱۰۰ برگِ تلاش برای پنج ایستگاهی که تجربه کردی.'}</p><div class="reward-note">${a.hints?'از راهنما کمک گرفتی و ادامه دادی؛ کمک‌خواستن هم یک مهارت است.':'مشاهده کردی، تصمیم گرفتی و راه‌حلت را آزمودی.'}</div>${m.local===20?`<p class="badge-celebration">نشان «${CHAPTERS[m.chapter].badge}» را هم گرفتی!</p>`:''}<div class="form-buttons"><button class="f-btn" data-action="next-mission" data-id="${Math.min(200,a.id+1)}">${a.id===200?'دیدن دفتر سفر':'دیدن قدم بعدی'}</button><button class="f-btn light" data-action="close">فعلاً استراحت می‌کنم</button></div>`,true);return;}
 if(a.kind==='toddler'){a.step++;if(a.step<3)showToddler();else finishToddler();return;}
 if(a.kind==='lesson'){a.step++;if(a.step<3)showLesson();else finishLesson();}
}
function startToddler(id){if(Date.now()<pauseUntil){showRest();return;}if(state.activeSeconds>=180){showRest(true);return;}modal(`<div class="modal-symbol">🌱</div><h2>یک بازی کوتاه، کنار یک بزرگ‌تر</h2><p class="story-paragraph">مامان، بابا یا مراقب کنار کودک بماند. پاسخ‌گفتن و ضبط صدا اجباری نیست. بازی را با خستگی یا بی‌میلی کودک تمام کنید.</p><button class="f-btn" data-action="toddler-begin" data-id="${id}">بزرگ‌تر کنار کودک است؛ شروع کنیم</button>`);}
function showToddler(){const a=active,t=TODDLER[a.id-1];a.ready=false;modal(`<div class="toddler-step-caption">${['بشنو و نگاه کن','نوبت تو؛ به هر روشی که دوست داری','بازی را به خانه ببریم'][a.step]}</div><div class="toddler-big-object">${objectArt(t.theme)}</div><h2>${t.title}</h2><div id="toddler-content"></div><div class="activity-navigation"><button class="f-btn" data-action="advance" id="advance-activity" disabled>${a.step===2?'پایانِ بازیِ کوتاه':'نوبت بعدی'} ${icon('arrow',17)}</button><button class="text-link" data-action="close">فعلاً کافی است</button></div>`,true);const root=$('#toddler-content');
 if(a.step===0){root.innerHTML=audioBar(t.audio,'بشنویم و با هم نگاه کنیم','toddler')+`<p class="toddler-prompt">${t.prompt}</p><div class="toddler-choice-objects">${['ball','water','apple'].map(o=>`<button data-object="${o}" aria-label="${{ball:'توپ',water:'آب',apple:'سیب'}[o]}">${objectArt(o)}</button>`).join('')}</div><p class="toddler-feedback" role="status">می‌توانی تصویر را لمس کنی یا فقط نگاه کنی.</p><button class="text-link" id="just-look">فعلاً فقط گوش دادیم و نگاه کردیم</button>`;root.querySelectorAll('[data-object]').forEach(b=>b.onclick=()=>{root.querySelectorAll('[data-object]').forEach(x=>x.classList.toggle('selected',b===x));root.querySelector('.toddler-feedback').textContent=b.dataset.object===t.theme?'این همان تصویر است! حالا با بزرگ‌تر بازی کن.':'این هم یک چیز دیگر است؛ با هم نگاه و کشف می‌کنیم.';missionReady();});$('#just-look').onclick=missionReady;}
 if(a.step===1){root.innerHTML=`<p class="toddler-prompt">${t.parent}</p><div class="parent-tip"><strong>فرصت پاسخ بدهید</strong><p>چند لحظه صبر کنید. اشاره، نگاه یا هر تلاش گفتاری را بپذیرید. لازم نیست کودک برای رفتن به قدم بعد کلمه را تکرار کند.</p></div>${recorderMarkup()}<button class="f-btn light" id="toddler-turn">فرصتِ نوبت‌گیری را داشتیم</button>`;$('#toddler-turn').onclick=()=>{a.ready=true;$('#advance-activity').disabled=false;};attachRecorder();}
 if(a.step===2){root.innerHTML=`<p class="toddler-prompt">حالا صفحه را کنار بگذاریم و ${t.word} را با کمک بزرگ‌تر در دنیای واقعی پیدا کنیم.</p><div class="safety-note">${t.theme==='ball'?'توپ بزرگ و نرم، بدون قطعهٔ جداشدنی؛ روی زمین امن.':t.theme==='water'?'هر مقدار آب فقط با نظارت مستقیم؛ کودک را کنار آب تنها نگذارید.':'این مرحله خوردن اجباری ندارد. میوهٔ سفت و تکهٔ بزرگ برای خوردن خردسال ایمن نیست؛ آماده‌سازی مناسب با بزرگ‌تر است.'}</div><p>بزرگ‌تر، چه چیزی مشاهده کردید؟</p><div class="reflection-options">${['با نگاه یا اشاره همراه شد','تلاشی برای گفتن داشت','فعلاً علاقه‌ای نشان نداد'].map(t=>`<button data-observation="${t}">${t}</button>`).join('')}</div>`;root.querySelectorAll('[data-observation]').forEach(b=>b.onclick=()=>{a.observation=b.dataset.observation;root.querySelectorAll('[data-observation]').forEach(x=>x.classList.toggle('selected',x===b));missionReady();});}
}
function finishToddler(){const a=active;log(state,'toddler','toddler',a.id,{observation:a.observation});save();active=null;render();modal(`<div class="modal-symbol">🌷</div><h2>چه خوب که با هم بودیم.</h2><p class="story-paragraph">حالا وقت بازی واقعی، حرکت یا استراحت است. لازم نیست بلافاصله بازی دیگری شروع شود.</p><p class="notice-note">مشاهدهٔ شما ثبت شد؛ هیچ نمرهٔ تلفظ یا تشخیص رشد داده نشد.</p><button class="f-btn" data-action="close">پایانِ این نوبت</button>`);}
function startLesson(id){active={kind:'lesson',id,step:0,ready:false};showLesson();}
function showLesson(){const a=active,l=LESSONS[a.id-1];a.ready=false;modal(`<span class="overline">کارگاهِ همراهی · قدم ${fa(a.step+1)} از ۳</span><h2>${l.title}</h2><div id="lesson-content"></div><div class="activity-navigation"><button id="advance-activity" class="f-btn" data-action="advance" disabled>${a.step===2?'ثبت این تمرین':'قدم بعدی'}</button><button class="text-link" data-action="close">بعداً برمی‌گردم</button></div>`,true);const root=$('#lesson-content');
 if(a.step===0){const shift=l.id%3,options=l.choices.map((t,i)=>({t,i}));options.push(...options.splice(0,shift));root.innerHTML=`<div class="parent-scenario">${l.situation}</div><p class="story-paragraph">کدام پاسخ، هم ایمنی و حد را حفظ می‌کند و هم احترام را؟</p><div class="answer-options">${options.map(o=>`<button data-parent-choice="${o.i}">${o.t}</button>`).join('')}</div><div class="story-feedback" role="status"></div>`;root.querySelectorAll('[data-parent-choice]').forEach(b=>b.onclick=()=>{if(+b.dataset.parentChoice===0){b.classList.add('right');root.querySelector('.story-feedback').textContent=l.why;missionReady();root.querySelectorAll('[data-parent-choice]').forEach(x=>x.disabled=true);}else root.querySelector('.story-feedback').textContent='این پاسخ ممکن است فشار یا ترس را بیشتر کند. به ایمنی، حد روشن و شنیدن نیاز کودک فکر کنید؛ فرصت دیگری دارید.';});}
 if(a.step===1){root.innerHTML=`${[1,2,15].includes(l.id)?audioBar('parent-repair','راهنمای صوتی آرام‌کردن و ترمیم',state.role):audioBar(state.role+'-welcome','مقدمهٔ راهنمای والدین؛ متن تمرین پایین است',state.role)}<div class="say-this"><small>می‌توانی این‌طور بگویی</small><blockquote>«${l.say}»</blockquote></div><p class="story-paragraph">${l.why}</p><label class="checkbox-label"><input id="practice-sentence" type="checkbox"> این جمله را خواندم و یک بار با لحن خودم تمرین کردم.</label>`;$('#practice-sentence').onchange=e=>{a.ready=e.target.checked;$('#advance-activity').disabled=!a.ready;};}
 if(a.step===2){root.innerHTML=`<div class="real-practice"><span>🌱</span><h3>یک قدم در زندگی واقعی</h3><p>${l.practice}</p></div><p class="story-paragraph">بعد از امتحان‌کردن، تجربه‌ات را انتخاب کن. اگر هنوز فرصت نکرده‌ای، بعداً برگرد.</p><div class="reflection-options">${['امتحان کردم؛ کمک‌کننده بود','امتحان کردم؛ هنوز تمرین می‌خواهم','امتحان کردم؛ نیاز به همراهی بیشتری دارم'].map(t=>`<button data-parent-reflect="${t}">${t}</button>`).join('')}</div><textarea id="parent-note" maxlength="300" placeholder="یادداشت اختیاری؛ بدون اطلاعات شناسایی کودک"></textarea>`;root.querySelectorAll('[data-parent-reflect]').forEach(b=>b.onclick=()=>{a.reflection=b.dataset.parentReflect;root.querySelectorAll('[data-parent-reflect]').forEach(x=>x.classList.toggle('selected',x===b));missionReady();});}
}
function finishLesson(){const a=active;log(state,state.role,'lesson',a.id,{reflection:a.reflection,note:$('#parent-note')?.value||''});save();active=null;render();modal(`<div class="modal-symbol">🌱</div><h2>یک قدمِ واقعی ثبت شد.</h2><p class="story-paragraph">این ثبت، نمرهٔ مادر یا پدر بودن نیست. تجربه‌ات کمک می‌کند تمرین بعدی را آگاهانه انتخاب کنی.</p><button class="f-btn" data-action="close">برگشت به برنامه</button>`);}
function showTogether(id){const t=TOGETHER[id-1];modal(`<span class="overline">بازی مشترک · ${t.time}</span><h2>${t.icon} ${t.name}</h2><p class="story-paragraph">وسایل: ${t.materials}</p><div class="family-role-instructions"><article><b>نقش کودک بزرگ‌تر</b><p>${t.big}</p></article><article><b>نقش خردسال</b><p>${t.small}</p></article><article><b>نقش بزرگ‌تر و ایمنی</b><p>${t.adult}</p></article></div><p class="story-paragraph">پس از بازی: ${t.reflect}</p><label class="checkbox-label"><input id="together-done" type="checkbox"> با همراهی بزرگ‌تر، بازی یا شکل مناسب آن را انجام دادیم.</label><button class="f-btn" id="save-together" disabled>این تجربه را ثبت کن</button>`,true);$('#together-done').onchange=e=>$('#save-together').disabled=!e.target.checked;$('#save-together').onclick=()=>{log(state,state.role,'together',id,{reflection:'بازی مشترک با نقش متناسب هر سن انجام شد.'});save();closeModal();render();toast('یک تجربهٔ مشترک ثبت شد.');};}
function recorderMarkup(){return `<section class="voice-response"><h3>${icon('mic',18)} اگر دوست داری، با صدایت تعریف کن</h3><p>فقط برای شنیدن صدای خودت. نمره‌گذاری یا ارسال به سرور ندارد؛ با بستن این پنجره حذف می‌شود.</p><label class="checkbox-label"><input id="record-consent" type="checkbox"> با اطلاع و اجازهٔ والد، ضبط کوتاه را می‌خواهم.</label><div class="form-buttons"><button class="f-btn light" id="record-start" type="button">ضبط تا ۲۰ ثانیه</button><button class="f-btn light" id="record-stop" type="button" disabled>توقف</button><button class="text-link" id="record-delete" type="button">حذف ضبط</button></div><p id="record-status" role="status"></p><audio id="record-playback" controls hidden></audio><small>اگر میکروفن در دسترس نیست، برای بزرگ‌تر تعریف کن؛ ضبط شرط ادامه نیست.</small></section>`;}
function attachRecorder(){let stream=null,recorder=null,url=null,timer=null,disposed=false;const oldCleanup=cleanup;function clearRecording(){clearTimeout(timer);if(recorder&&recorder.state!=='inactive')recorder.stop();stream?.getTracks().forEach(t=>t.stop());stream=null;if(url){URL.revokeObjectURL(url);url=null;}}cleanup=()=>{disposed=true;clearRecording();oldCleanup();};$('#record-start').onclick=async()=>{if(!$('#record-consent').checked){$('#record-status').textContent='ضبط فقط پس از اجازهٔ والد و انتخاب خودت شروع می‌شود.';return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){$('#record-status').textContent='ضبط در این دستگاه پشتیبانی نمی‌شود؛ بدون ضبط ادامه بده.';return;}clearRecording();$('#record-start').disabled=true;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(disposed){stream.getTracks().forEach(t=>t.stop());return;}recorder=new MediaRecorder(stream);let chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{stream?.getTracks().forEach(t=>t.stop());if(disposed)return;url=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));$('#record-playback').src=url;$('#record-playback').hidden=false;$('#record-status').textContent='آمادهٔ شنیدن؛ فقط در همین پنجره نگه داشته می‌شود.';$('#record-start').disabled=false;$('#record-stop').disabled=true;};recorder.start();$('#record-status').textContent='در حال ضبط…';$('#record-stop').disabled=false;timer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},20000);}catch{stream?.getTracks().forEach(t=>t.stop());if(!disposed){$('#record-start').disabled=false;$('#record-status').textContent='اجازهٔ میکروفن داده نشد یا ضبط در دسترس نیست. می‌توانی بدون ضبط ادامه بدهی.';}}};$('#record-stop').onclick=()=>{clearTimeout(timer);if(recorder?.state==='recording')recorder.stop();};$('#record-delete').onclick=()=>{if(recorder?.state==='recording'){recorder.onstop=null;}clearRecording();$('#record-playback').pause();$('#record-playback').removeAttribute('src');$('#record-playback').hidden=true;$('#record-start').disabled=false;$('#record-stop').disabled=true;$('#record-status').textContent='ضبط حذف شد.';};}
function draw(){const suspended=active;modal(`<h2>کارگاهِ خیال</h2><p class="story-paragraph">ایده‌ات را نقاشی کن؛ درست و غلط ندارد.</p><div class="drawing-palette">${['#7b65b9','#70a78b','#e6a366','#d9828e','#516c96'].map(c=>`<button data-color="${c}" style="background:${c}" aria-label="رنگ ${c}"></button>`).join('')}<button id="clear-drawing">پاک کن</button></div><canvas id="family-drawing" width="700" height="440" aria-label="صفحهٔ نقاشی"></canvas><div class="form-buttons"><button class="f-btn light" id="stamp-drawing">یک ستاره اضافه کن</button><button class="f-btn" id="save-drawing">ذخیره و برگشت</button></div>`,true);active=suspended;let c=$('#family-drawing'),ctx=c.getContext('2d'),drag=false,marked=false,color='#7b65b9';const reset=()=>{ctx.fillStyle='#fffdf8';ctx.fillRect(0,0,700,440);marked=false;};reset();ctx.lineWidth=7;ctx.lineCap='round';const pt=e=>{let b=c.getBoundingClientRect();return [(e.clientX-b.left)*700/b.width,(e.clientY-b.top)*440/b.height];};c.onpointerdown=e=>{drag=true;marked=true;c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...pt(e));};c.onpointermove=e=>{if(drag){ctx.strokeStyle=color;ctx.lineTo(...pt(e));ctx.stroke();}};c.onpointerup=c.onpointercancel=()=>drag=false;document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>color=b.dataset.color);$('#clear-drawing').onclick=reset;$('#stamp-drawing').onclick=()=>{ctx.font='80px sans-serif';ctx.fillStyle=color;ctx.fillText('★',40+Math.random()*500,110+Math.random()*200);marked=true;};$('#save-drawing').onclick=()=>{if(!marked){toast('اگر دوست داری اول یک خط بکش یا ستاره اضافه کن.');return;}state.art.push(c.toDataURL('image/png'));state.art=state.art.slice(-6);save();if(suspended){active=suspended;showMission();}else{closeModal();render();}toast('نقاشی در دفتر خانواده ذخیره شد.');};}
function gate(callback){if(['mother','father'].includes(state.role)){callback();return;}const a=13+Math.floor(Math.random()*8),b=9+Math.floor(Math.random()*8);gateNext=callback;modal(`<span class="modal-symbol small">🌿</span><h2>این بخش را با بزرگ‌تر باز کن</h2><p class="story-paragraph">این سؤال فقط یادآوری حضور والد است، نه رمز امنیتی.</p><div class="gate-sum" dir="ltr">${fa(a)} + ${fa(b)} = ؟</div><form id="parent-gate"><input aria-label="پاسخ سؤال والد" id="gate-answer" inputmode="numeric" required><button class="f-btn">ادامه با والد</button><p id="gate-error" role="status"></p></form>`);$('#parent-gate').onsubmit=e=>{e.preventDefault();const val=$('#gate-answer').value.replace(/[۰-۹]/g,x=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(x)).replace(/[٠-٩]/g,x=>'٠١٢٣٤٥٦٧٨٩'.indexOf(x));if(+val===a+b){const cb=gateNext;closeModal();cb();}else $('#gate-error').textContent='پاسخ را دوباره بررسی کنید.';};}
function exportBackup(){const data={...state,serverUrl:'',drafts:{},activeSeconds:0};const text=JSON.stringify(data,null,2);if(window.AndroidReport){window.AndroidReport.exportReport(text);return;}const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='bagh-family-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('فایل پشتیبان شامل اطلاعات خصوصی خانواده است؛ امن نگه دارید.');}
function showRest(required=false){if(required&&Date.now()>=pauseUntil)pauseUntil=Date.now()+60000;active=null;modal(`<div class="modal-symbol">🌿</div><h2>باغ عجله‌ای ندارد.</h2><p class="story-paragraph">از صفحه فاصله بگیر، کمی حرکتِ راحت انجام بده یا کنار یک بزرگ‌تر استراحت کن. بازی واقعی هم بخشی از ماجراجویی است.</p><p id="rest-message">${Date.now()<pauseUntil?'یک دقیقه فرصتِ فاصله‌گرفتن از صفحه.':'هر وقت آماده بودی، خودت انتخاب کن که برگردی.'}</p><button class="f-btn" id="finish-rest" ${Date.now()<pauseUntil?'disabled':''}>${Date.now()<pauseUntil?'کمی استراحت کنیم':'برگشت به خانه'}</button>`);const t=setInterval(()=>{if(Date.now()>=pauseUntil){clearInterval(t);state.activeSeconds=0;save();if($('#finish-rest')){$('#finish-rest').disabled=false;$('#finish-rest').textContent='اگر آماده‌ای، برگرد';}}},1000);cleanup=()=>clearInterval(t);$('#finish-rest').onclick=()=>{state.activeSeconds=0;save();closeModal();render();};}
function bindForms(){
 if($('#settings-form'))$('#settings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.names.explorer=String(f.get('explorer')).trim().slice(0,24)||'کاوشگر';state.names.toddler=String(f.get('toddler')).trim().slice(0,24)||'جوانه';state.cycleStart=String(f.get('cycle'));state.limit=+f.get('limit');save();render();toast('تنظیمات ذخیره شد.');};
 if($('#server-form'))$('#server-form').onsubmit=e=>{e.preventDefault();let url=String(new FormData(e.target).get('server')).trim().replace(/\/$/,'');if(url){try{let u=new URL(url);if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash||u.pathname!=='/')throw Error();url=u.origin;}catch{toast('یک نشانی HTTPS معتبر، بدون مسیر یا رمز وارد کنید.');return;}}sync.reset();state.serverUrl=url;window.FamilyNative?.configureSync(url);save();render();toast('نشانی تغییر کرد؛ دوباره وارد حساب والدین شوید.');};
 if($('#login-form'))$('#login-form').onsubmit=async e=>{e.preventDefault();const form=e.target,f=new FormData(form),buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);$('#login-status').textContent='در حال ارتباط…';if(navigator.userAgent.includes('LittleStarAndroid')&&!state.serverUrl){$('#login-status').textContent='ابتدا نشانی سرور HTTPS مستقرشده را تنظیم کنید.';buttons.forEach(b=>b.disabled=false);return;}try{await sync.login(String(f.get('username')),String(f.get('password')),e.submitter.value==='register');form.reset();render();toast('وارد حساب خانواده شدید. هنوز گزارشی ارسال نشده؛ دکمهٔ همگام‌سازی را بزنید.');}catch(err){if($('#login-status'))$('#login-status').textContent=err.message;buttons.forEach(b=>b.disabled=false);}};
 if($('#import-backup'))$('#import-backup').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024){toast('فایل بزرگ‌تر از حد مجاز است.');return;}try{const raw=JSON.parse((await file.text()).replace(/^\uFEFF/,''));if(raw.version!==2||!Array.isArray(raw.events))throw Error();const imported=normalize(raw);state.events=mergeEvents(state.events,imported.events);for(const a of imported.art)if(!state.art.includes(a))state.art.push(a);state.art=state.art.slice(-6);save();render();toast('تجربه‌های فایل با اطلاعات این دستگاه ترکیب شدند؛ تنظیمات دستگاه تغییر نکرد.');}catch{toast('این فایل، پشتیبان معتبر نسخهٔ ۲ نیست.');}};
}
const actions={
 'review-child':el=>{const role=el.dataset.role;modal(`<h2>خبرهای ${esc(state.names[role])}</h2><p class="notice-note">این‌ها ثبت فعالیت و مشاهده‌اند؛ نه ارزیابی هوش یا تشخیص شخصیت.</p><div class="child-review">${state.events.filter(e=>e.role===role).slice(-8).reverse().map(e=>`<article><strong>${esc(eventTitle(e))}</strong><p>${esc(e.data.observation||e.data.reflection||e.data.interest||'تجربه ثبت شد')}</p><small>${e.kind==='mission'?`راهنما: ${fa(e.data.hints||0)} بار · انتخاب‌های نیازمند بازنگری: ${fa(e.data.attempts||0)}`:''}</small></article>`).join('')||'<p>هنوز گزارشی نداریم. از فعالیت محلی یا همگام‌سازی خانواده شروع کنید.</p>'}</div>`);},
 'profile':()=>modal(`<h2>همراهِ خانواده</h2>${fixedRole?`<p class="story-paragraph">نسخهٔ ${currentRole().name}</p>`:`<div class="profile-roles">${ROLES.map(r=>`<button data-action="role" data-role="${r.id}"><span>${r.icon}</span><strong>${r.name}</strong><small>${r.age}</small></button>`).join('')}</div>`}<div class="form-buttons"><button class="f-btn light" data-action="protected-page" data-page="connect">ارتباط خانواده</button><button class="f-btn light" data-action="protected-page" data-page="settings">تنظیمات والدین</button></div>`),
 'page':el=>{closeModal();page=el.dataset.page;voiceRole=state.role;render();window.scrollTo(0,0);},
 'protected-page':el=>gate(()=>{closeModal();page=el.dataset.page;render();window.scrollTo(0,0);}),
 'role':el=>{if(fixedRole)return;closeModal();state.role=el.dataset.role;voiceRole=state.role;page='home';save();render();window.scrollTo(0,0);},
 'chapter':el=>{chapter=+el.dataset.id;page='journey';render();window.scrollTo(0,0);},
 'mission':el=>startMission(+el.dataset.id),
 'next-mission':el=>{const id=+el.dataset.id;closeModal();if(doneMissions().size===200){page='journal';render();}else startMission(id);},
 'advance':advance,'close':closeModal,
 'toddler':el=>startToddler(+el.dataset.id),
 'toddler-begin':el=>{active={kind:'toddler',id:+el.dataset.id,step:0,ready:false};showToddler();},
 'lesson':el=>startLesson(+el.dataset.id),'together':el=>showTogether(+el.dataset.id),
 'energy':el=>{state.energy=el.dataset.value;save();render();},
 'routine':el=>{const key=today()+':'+el.dataset.id;if(!completions(state,state.role,'routine').has(key))log(state,state.role,'routine',key,{});save();render();},
 'favorite':el=>{const id=+el.dataset.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();},
 'voice-role':el=>{voiceRole=el.dataset.role;render();},
 'preview-voice':el=>playAudio(voiceRole+'-welcome',voiceRole,el.dataset.value),
 'select-voice':el=>{state.voices[voiceRole]=el.dataset.value;save();render();toast('صدای این نقش ذخیره شد.');},
 'audio':el=>playAudio(el.dataset.clip,el.dataset.role),
 'stop-audio':stopAudio,'sound':()=>{state.sound=!state.sound;save();render();},
 'rest':()=>showRest(),'draw':draw,'export':exportBackup,'protected-export':()=>gate(exportBackup),
 'sync':async()=>{if(syncBusy)return;syncBusy=true;render();try{const events=await sync.sync(state.events);state.events=mergeEvents(state.events,events);save();syncBusy=false;render();$('#sync-status').textContent='همگام‌سازی انجام شد؛ '+fa(state.events.length)+' تجربه در این دستگاه.';}catch(e){syncBusy=false;render();if($('#sync-status'))$('#sync-status').textContent=e.message;else toast(e.message);}},
 'logout':async()=>{await sync.logout();render();},
 'delete-account':()=>{modal(`<h2>حذف گزارش‌های سرور؟</h2><p class="story-paragraph">این کار حساب و گزارش‌های همان سرور را حذف می‌کند. داده‌های محلی دستگاه باقی می‌مانند. برای تأیید رمز را دوباره وارد کنید.</p><form id="delete-server"><input type="password" name="password" minlength="10" maxlength="128" required aria-label="رمز حساب"><button class="danger-btn">حذف حساب سرور</button><p id="delete-error" role="status"></p></form>`);$('#delete-server').onsubmit=async e=>{e.preventDefault();try{await sync.remove(new FormData(e.target).get('password'));closeModal();render();toast('حساب و گزارش‌های سرور حذف شدند.');}catch(err){$('#delete-error').textContent=err.message;}};},
 'reset':()=>{modal(`<h2>اطلاعات همین دستگاه پاک شود؟</h2><p class="story-paragraph">پیشرفت و نقاشی‌های محلی حذف می‌شوند. اطلاعات سرور حذف نمی‌شود و همگام‌سازی بعدی ممکن است آن‌ها را برگرداند. قبل از حذف، پشتیبان بگیرید.</p><button class="danger-btn" id="confirm-reset">بله، اطلاعات محلی را پاک کن</button><button class="f-btn light" data-action="close">انصراف</button>`);$('#confirm-reset').onclick=()=>{sync.reset();state=fresh();if(fixedRole)state.role=fixedRole;save();closeModal();page='home';render();toast('دستگاه برای یک شروع تازه آماده شد.');};}
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=actions[el.dataset.action];if(action){e.preventDefault();Promise.resolve(action(el)).catch(()=>toast('این کار انجام نشد؛ دوباره امتحان کنید.'));}});
document.addEventListener('keydown',e=>{if(!$('.f-modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const list=[...$('.f-modal').querySelectorAll('button:not([disabled]),input:not([hidden]),textarea,select,a[href]')].filter(e=>e.offsetParent!==null),first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.familyPause=()=>{stopAudio();cleanup();cleanup=()=>{};if(active){saveDraft();closeModal();toast('فعالیت ذخیره شد؛ هر وقت آماده‌ای ادامه بده.');}};
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')window.familyPause();});
setInterval(()=>{if(document.visibilityState==='visible'&&active&&['mission','toddler'].includes(active.kind)){state.activeSeconds+=5;save();const limit=active.kind==='toddler'?180:state.limit*60;if(state.activeSeconds>=limit){saveDraft();showRest(true);}}},5000);
window.FamilyNative?.configureSync(state.serverUrl);render();paintEmoji();emojiObserver.observe(document.body,{childList:true,subtree:true});
if('serviceWorker'in navigator&&!import.meta.env.DEV&&!navigator.userAgent.includes('LittleStarAndroid'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
